update lessons set tasks=replace(tasks::text,$q$Тед подзвонив Вікторії й чесно розповів про повідомлення від Робін. Вікторія сказала, що вони мусять розійтися.$q$,$q$Поки Тед був у Робін, йому подзвонила Вікторія — і слухавку взяла Робін. Наступного дня Тед подзвонив Вікторії й чесно розповів усе. Вікторія сказала, що вони мусять розійтися.$q$)::jsonb, variants=replace(variants::text,$q$Тед подзвонив Вікторії й чесно розповів про повідомлення від Робін. Вікторія сказала, що вони мусять розійтися.$q$,$q$Поки Тед був у Робін, йому подзвонила Вікторія — і слухавку взяла Робін. Наступного дня Тед подзвонив Вікторії й чесно розповів усе. Вікторія сказала, що вони мусять розійтися.$q$)::jsonb where course_id=(select id from courses where slug='himym-s1') and num=20;
update lessons set tasks=replace(tasks::text,$q$Ted zadzwonił do Victorii i szczerze opowiedział o wiadomości od Robin. Victoria powiedziała, że muszą się rozstać.$q$,$q$Kiedy Ted był u Robin, zadzwoniła Victoria — i telefon odebrała Robin. Następnego dnia Ted zadzwonił do Victorii i szczerze opowiedział jej wszystko. Victoria powiedziała, że muszą się rozstać.$q$)::jsonb, variants=replace(variants::text,$q$Ted zadzwonił do Victorii i szczerze opowiedział o wiadomości od Robin. Victoria powiedziała, że muszą się rozstać.$q$,$q$Kiedy Ted był u Robin, zadzwoniła Victoria — i telefon odebrała Robin. Następnego dnia Ted zadzwonił do Victorii i szczerze opowiedział jej wszystko. Victoria powiedziała, że muszą się rozstać.$q$)::jsonb where course_id=(select id from courses where slug='himym-s1') and num=20;
update lessons set tasks=replace(tasks::text,$q$Ted called Victoria and honestly told her about Robin's text. Victoria said they had to break up.$q$,$q$While Ted was at Robin's, Victoria called, and Robin answered his phone. The next day Ted called Victoria and honestly told her everything. Victoria said they had to break up.$q$)::jsonb, variants=replace(variants::text,$q$Ted called Victoria and honestly told her about Robin's text. Victoria said they had to break up.$q$,$q$While Ted was at Robin's, Victoria called, and Robin answered his phone. The next day Ted called Victoria and honestly told her everything. Victoria said they had to break up.$q$)::jsonb where course_id=(select id from courses where slug='himym-s1') and num=20;
