update lessons set tasks=replace(tasks::text,$q$Ти тримаєш мапу й підказуєш Джессіці, куди летіти, хоча за склом нічого не видно.$q$,$q$Того ж вечора на станції Пол і Джессіка розповідають, як утекли від Харконненів і полетіли просто в піщану бурю. Ти розгортаєш мапу й позначаєш їхній шлях, ніби сам тримав її в кабіні, хоча за склом нічого не було видно.$q$)::jsonb, variants=replace(variants::text,$q$Ти тримаєш мапу й підказуєш Джессіці, куди летіти, хоча за склом нічого не видно.$q$,$q$Того ж вечора на станції Пол і Джессіка розповідають, як утекли від Харконненів і полетіли просто в піщану бурю. Ти розгортаєш мапу й позначаєш їхній шлях, ніби сам тримав її в кабіні, хоча за склом нічого не було видно.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=26;
update lessons set tasks=replace(tasks::text,$q$Trzymasz mapę i podpowiadasz Jessice, dokąd lecieć, choć za szybą nic nie widać.$q$,$q$Tego samego wieczoru na stacji Paul i Jessica opowiadają, jak uciekli Harkonnenom i polecieli prosto w burzę piaskową. Rozkładasz mapę i zaznaczasz ich trasę, jakbyś sam trzymał ją w kabinie, choć za szybą nic nie było widać.$q$)::jsonb, variants=replace(variants::text,$q$Trzymasz mapę i podpowiadasz Jessice, dokąd lecieć, choć za szybą nic nie widać.$q$,$q$Tego samego wieczoru na stacji Paul i Jessica opowiadają, jak uciekli Harkonnenom i polecieli prosto w burzę piaskową. Rozkładasz mapę i zaznaczasz ich trasę, jakbyś sam trzymał ją w kabinie, choć za szybą nic nie było widać.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=26;
update lessons set tasks=replace(tasks::text,$q$You hold the map and tell Jessica which way to fly, although nothing can be seen through the glass.$q$,$q$That evening at the station, Paul and Jessica tell how they escaped the Harkonnens and flew straight into a sandstorm. You spread out the map and trace their route as if you had held it in the cockpit yourself, although nothing could be seen through the glass.$q$)::jsonb, variants=replace(variants::text,$q$You hold the map and tell Jessica which way to fly, although nothing can be seen through the glass.$q$,$q$That evening at the station, Paul and Jessica tell how they escaped the Harkonnens and flew straight into a sandstorm. You spread out the map and trace their route as if you had held it in the cockpit yourself, although nothing could be seen through the glass.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=26;
update lessons set tasks=replace(tasks::text,$q$Ти мав спати, але не можеш. Пол сидить із заплющеними очима й говорить дивні речі.$q$,$q$Ніч на станції Кайнс. Ти мав спати, але не можеш. Пол сидить із заплющеними очима й переказує матері видіння, яке мав у наметі після бурі, — дивні речі.$q$)::jsonb, variants=replace(variants::text,$q$Ти мав спати, але не можеш. Пол сидить із заплющеними очима й говорить дивні речі.$q$,$q$Ніч на станції Кайнс. Ти мав спати, але не можеш. Пол сидить із заплющеними очима й переказує матері видіння, яке мав у наметі після бурі, — дивні речі.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=29;
update lessons set tasks=replace(tasks::text,$q$Miałeś spać, ale nie możesz. Paul siedzi z zamkniętymi oczami i mówi dziwne rzeczy.$q$,$q$Noc na stacji Kynes. Miałeś spać, ale nie możesz. Paul siedzi z zamkniętymi oczami i opowiada matce wizję, którą miał w namiocie po burzy — dziwne rzeczy.$q$)::jsonb, variants=replace(variants::text,$q$Miałeś spać, ale nie możesz. Paul siedzi z zamkniętymi oczami i mówi dziwne rzeczy.$q$,$q$Noc na stacji Kynes. Miałeś spać, ale nie możesz. Paul siedzi z zamkniętymi oczami i opowiada matce wizję, którą miał w namiocie po burzy — dziwne rzeczy.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=29;
update lessons set tasks=replace(tasks::text,$q$You were supposed to sleep, but you can't. Paul sits with his eyes closed, saying strange things.$q$,$q$Night at Kynes's station. You were supposed to sleep, but you can't. Paul sits with his eyes closed, telling his mother the vision he had in the tent after the storm: strange things.$q$)::jsonb, variants=replace(variants::text,$q$You were supposed to sleep, but you can't. Paul sits with his eyes closed, saying strange things.$q$,$q$Night at Kynes's station. You were supposed to sleep, but you can't. Paul sits with his eyes closed, telling his mother the vision he had in the tent after the storm: strange things.$q$)::jsonb where course_id=(select id from courses where slug='dune-1') and num=29;
